begin;
select no_plan();
insert into auth.users(id,email,email_confirmed_at,aud,role) select ('d3000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'discount-'||n||'@example.test',now(),'authenticated','authenticated' from generate_series(1,5)n;
insert into public.basic_onboarding_applications(user_id,full_name,email,phone,linkedin_url,date_of_birth,status) select id,'Discount Test',email,'9999999999','https://linkedin.com/in/test','1990-01-01','approved' from auth.users where id::text like 'd3000000%';
insert into public.staff_roles(user_id,role) values('d3000000-0000-4000-8000-000000000001','admin'),('d3000000-0000-4000-8000-000000000004','membership_reviewer'),('d3000000-0000-4000-8000-000000000005','super_admin');
select set_config('request.jwt.claims','{"sub":"d3000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select set_config('discount.offer',(public.save_discount_offer(jsonb_build_object('name','Personal offer','audience','personal','member_id','d3000000-0000-4000-8000-000000000002','value_kind','percent','value',40,'categories',array['coworking'],'starts_at',now()-interval '1 day','ends_at',now()+interval '7 days'))).id::text,true);
select is((select personal_use from public.admin_discount_offers() where id=current_setting('discount.offer')::uuid),'once','personal defaults to one use');
select is((select count(*)::int from public.discount_offer_history(current_setting('discount.offer')::uuid)),1,'create audited');
select throws_ok($$select public.save_discount_offer('{}',current_setting('discount.offer')::uuid,0)$$,'40001','Offer changed; refresh before saving','stale revision blocked');
select lives_ok($$select public.save_discount_offer(to_jsonb(o)||'{"personal_use":"repeat_until_expiry","per_member_limit":2}',o.id,o.revision) from public.discount_offers o where id=current_setting('discount.offer')::uuid$$,'repeat until expiry supported');
select lives_ok($$select public.save_discount_offer(to_jsonb(o)||'{"personal_use":"once","per_member_limit":null}',o.id,o.revision) from public.discount_offers o where id=current_setting('discount.offer')::uuid$$,'restore once for ledger');
select set_config('request.jwt.claims','{"sub":"d3000000-0000-4000-8000-000000000004","role":"authenticated"}',true);
select throws_ok($$select public.admin_discount_offers()$$,'42501','Website Admin required','staff cannot list offers');
select throws_ok($$select public.save_discount_offer('{}')$$,'42501','Website Admin required','staff cannot create offers');
select throws_ok($$select public.discount_offer_history(current_setting('discount.offer')::uuid)$$,'42501','Website Admin required','staff cannot read audit');
select ok(not has_table_privilege('authenticated','public.discount_offers','select'),'direct table read blocked');
select ok(not has_table_privilege('authenticated','public.discount_offers','insert'),'direct insertion blocked');
select ok(not has_function_privilege('authenticated','public.reserve_discount_quote(uuid,uuid,text)','execute'),'members cannot reserve uses');
select ok(not has_function_privilege('authenticated','public.settle_discount_reservation(uuid,boolean)','execute'),'members cannot consume uses');
select ok(not has_function_privilege('service_role','private.make_discount_quote(uuid,text,bigint,bigint,text)','execute'),'service cannot supply arbitrary price through private helper');
select is(public.public_discount_offers(),'[]'::jsonb,'personal offers not public');
select is(public.my_discount_offers(),'[]'::jsonb,'another member sees no private offers');
select set_config('request.jwt.claims','{"sub":"d3000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is(jsonb_array_length(public.my_discount_offers()),1,'target sees personal offer');
update public.booking_products set price_paise=50000,enabled=true where code='workspace-day';
select set_config('discount.quote',public.quote_discounted_access((select id from public.booking_products where code='workspace-day'),array[date '2030-01-07'])::text,true);
select is((current_setting('discount.quote')::jsonb->>'payable_paise')::bigint,30000::bigint,'40 percent from server product price');
select set_config('discount.second',public.quote_discounted_access((select id from public.booking_products where code='workspace-day'),array[date '2030-01-08'])::text,true);
select set_config('discount.reserve',public.reserve_discount_quote((current_setting('discount.quote')::jsonb->>'discount_quote_id')::uuid,auth.uid(),'discount-test-once')::text,true);
select is(public.reserve_discount_quote((current_setting('discount.quote')::jsonb->>'discount_quote_id')::uuid,auth.uid(),'discount-test-once')::text,current_setting('discount.reserve'),'same idempotency returns same reservation');
select throws_ok($$select public.reserve_discount_quote((current_setting('discount.second')::jsonb->>'discount_quote_id')::uuid,auth.uid(),'discount-test-once')$$,'22023','Idempotency key conflict','key cannot switch quotes');
select throws_ok($$select public.reserve_discount_quote((current_setting('discount.second')::jsonb->>'discount_quote_id')::uuid,auth.uid(),'discount-test-second')$$,'40001','Offer changed or exhausted; requote','reserved one use blocks another quote');
select lives_ok($$select public.settle_discount_reservation(current_setting('discount.reserve')::uuid,false)$$,'failed checkout releases use');
select set_config('discount.reserve2',public.reserve_discount_quote((current_setting('discount.second')::jsonb->>'discount_quote_id')::uuid,auth.uid(),'discount-test-second')::text,true);
select lives_ok($$select public.settle_discount_reservation(current_setting('discount.reserve2')::uuid,true)$$,'capture consumes once');
select lives_ok($$select public.settle_discount_reservation(current_setting('discount.reserve2')::uuid,true)$$,'capture idempotent');
select throws_ok($$select public.settle_discount_reservation(current_setting('discount.reserve2')::uuid,false)$$,'22023','Reservation no longer active','captured use cannot be silently returned on refund');
select is((public.quote_discounted_access((select id from public.booking_products where code='workspace-day'),array[date '2030-01-09'])->>'payable_paise')::bigint,50000::bigint,'used personal offer no longer applies');
select set_config('request.jwt.claims','{"sub":"d3000000-0000-4000-8000-000000000005","role":"authenticated"}',true);
select lives_ok($$select public.save_discount_offer(jsonb_build_object('name','Student verified','audience','student','member_id','d3000000-0000-4000-8000-000000000003','value_kind','percent','value',20,'categories',array['coworking'],'stack_with_launch',true,'personal_use','repeat_until_expiry','starts_at',now()-interval '1 day','ends_at',now()+interval '7 days'))$$,'super admin assigns verified student offer');
select throws_like($$select public.save_discount_offer(jsonb_build_object('name','Bad student','audience','student','member_id','d3000000-0000-4000-8000-000000000003','value_kind','percent','value',21,'categories',array['coworking'],'stack_with_launch',true,'starts_at',now()-interval '1 day','ends_at',now()+interval '7 days'))$$,'%check constraint%','student capped at20');
select is((private.make_discount_quote('d3000000-0000-4000-8000-000000000003','coworking',50000,15000)->>'payable_paise')::bigint,28000::bigint,'student20 applied after launch30');
select is((private.make_discount_quote('d3000000-0000-4000-8000-000000000003','equipment',50000,0)->>'payable_paise')::bigint,50000::bigint,'student does not apply to equipment');
select lives_ok($$select public.save_discount_offer(jsonb_build_object('name','Special week','audience','public','value_kind','fixed','value',10000,'categories',array['coworking'],'starts_at',now()-interval '1 day','ends_at',now()+interval '7 days'))$$,'public fixed discount');
select is(jsonb_array_length(public.public_discount_offers()),1,'public projection includes only public');
select ok(not (public.public_discount_offers()->0 ? 'member_id') and not(public.public_discount_offers()->0 ? 'code'),'public projection private fields excluded');
select lives_ok($$select public.save_discount_offer(jsonb_build_object('name','Coupon','audience','code','code','launch50','value_kind','percent','value',50,'categories',array['coworking'],'starts_at',now()-interval '1 day','ends_at',now()+interval '7 days'))$$,'coupon normalized');
select is((private.make_discount_quote('d3000000-0000-4000-8000-000000000003','coworking',50000,15000,'LAUNCH50')->>'payable_paise')::bigint,25000::bigint,'best offer beats launch and student without stacking');
select is((private.make_discount_quote('d3000000-0000-4000-8000-000000000003','coworking',50000,15000,'WRONG')->>'payable_paise')::bigint,28000::bigint,'unmatched code does not grant discount');
select ok(not exists(select 1 from public.paid_access_entitlements where user_id::text like 'd3000000%'),'no entitlements issued');
-- Exercise actual SQL privileges, not only JWT branches under the test owner.
set local role authenticated;
select lives_ok($$select public.admin_discount_offers()$$,'authenticated super admin can list');
select lives_ok($$select public.admin_discount_member('d3000000-0000-4000-8000-000000000002')$$,'admin resolves target identity');
select throws_ok($$select * from public.discount_offers$$,'42501','permission denied for table discount_offers','direct authenticated read blocked');
select throws_ok($$select public.reserve_discount_quote(null,null,null)$$,'42501','permission denied for function reserve_discount_quote','authenticated cannot redeem');
select set_config('request.jwt.claims','{"sub":"d3000000-0000-4000-8000-000000000004","role":"authenticated"}',true);
select throws_ok($$select public.admin_discount_offers()$$,'42501','Website Admin required','actual staff role cannot list');
select throws_ok($$select public.admin_discount_member('d3000000-0000-4000-8000-000000000002')$$,'42501','Website Admin required','actual staff role cannot resolve identities');
reset role;
set local role anon;
select lives_ok($$select public.public_discount_offers()$$,'anonymous public offers allowed');
select throws_ok($$select public.my_discount_offers()$$,'42501','permission denied for function my_discount_offers','anonymous private list blocked');
reset role;
select throws_ok($$select public.reserve_discount_quote(null,null,null)$$,'22023','Valid quote, member and idempotency key required','service adapter rejects null');
select set_config('request.jwt.claims','{"sub":"d3000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.admin_preview_discount_access('d3000000-0000-4000-8000-000000000003',(select id from public.booking_products where code='workspace-week'),array[date '2026-12-29'])$$,'22023','Pass crossing launch expiry requires pricing review','cross-year pass is not silently repriced');
select is((select breakdown->>'tax_status' from private.discount_quotes where id=(current_setting('discount.quote')::jsonb->>'discount_quote_id')::uuid),'not_configured_pre_tax_only','access snapshot explicitly pre-tax');
select is((select breakdown->'access_quote'->>'product_id' from private.discount_quotes where id=(current_setting('discount.quote')::jsonb->>'discount_quote_id')::uuid),(select id::text from public.booking_products where code='workspace-day'),'source product saved immutably');
select ok((select breakdown ? 'resource_id' from private.discount_quotes where id=(current_setting('discount.quote')::jsonb->>'discount_quote_id')::uuid),'source resource saved explicitly');
select set_config('discount.cap',(public.save_discount_offer(jsonb_build_object('name','Cap at zero','audience','personal','member_id','d3000000-0000-4000-8000-000000000003','value_kind','fixed','value',999999,'categories',array['equipment'],'starts_at',now()-interval '1 day','ends_at',now()+interval '7 days'))).id::text,true);
select is((private.make_discount_quote('d3000000-0000-4000-8000-000000000003','equipment',10000,0)->>'payable_paise')::bigint,0::bigint,'fixed discount capped at price');
select public.save_discount_offer(to_jsonb(o)||'{"state":"paused"}',o.id,o.revision) from public.discount_offers o where id=current_setting('discount.cap')::uuid;
select is((private.make_discount_quote('d3000000-0000-4000-8000-000000000003','equipment',10000,0)->>'payable_paise')::bigint,10000::bigint,'paused excluded');
select public.save_discount_offer(to_jsonb(o)||jsonb_build_object('state','active','starts_at',now()+interval '1 day'),o.id,o.revision) from public.discount_offers o where id=current_setting('discount.cap')::uuid;
select is((private.make_discount_quote('d3000000-0000-4000-8000-000000000003','equipment',10000,0)->>'payable_paise')::bigint,10000::bigint,'future promotion excluded');
select public.save_discount_offer(to_jsonb(o)||jsonb_build_object('starts_at',now()-interval '2 days','ends_at',now()-interval '1 day'),o.id,o.revision) from public.discount_offers o where id=current_setting('discount.cap')::uuid;
select is((private.make_discount_quote('d3000000-0000-4000-8000-000000000003','equipment',10000,0)->>'payable_paise')::bigint,10000::bigint,'expired excluded');
-- Equipment is a snapshot overlay; existing rental quote/payment values must remain untouched.
insert into public.resources(id,location_id,slug,name,kind,capacity,max_guests,max_duration_minutes,booking_horizon_days) select 'd5000000-0000-4000-8000-000000000001',id,'discount-equipment','Discount fixture','equipment',1,0,1440,10000 from public.locations limit 1;
insert into public.inventory_locations(id,lab_location_id,code,name) select 'd5000000-0000-4000-8000-000000000002',id,'DISCOUNT-TEST','Discount test' from public.locations limit 1;
insert into public.asset_units(id,component_id,inventory_location_id,asset_tag) select 'd5000000-0000-4000-8000-000000000003',id,'d5000000-0000-4000-8000-000000000002','ARM-DISCOUNT-990004' from public.components limit 1;
insert into public.equipment_rental_units(id,asset_unit_id,resource_id,reason) values('d5000000-0000-4000-8000-000000000004','d5000000-0000-4000-8000-000000000003','d5000000-0000-4000-8000-000000000001','Synthetic discount fixture');
insert into public.equipment_rental_rates(id,unit_id,charge_unit,tax_bps,price_paise,valid_from,approved_by) values('d5000000-0000-4000-8000-000000000005','d5000000-0000-4000-8000-000000000004','hour',1800,10000,now()-interval '1 day',auth.uid());
insert into public.equipment_rental_quotes(id,user_id,operator_id,rate_id,starts_at,ends_at,dates,amount_paise,tax_paise,total_paise,expires_at) values('d5000000-0000-4000-8000-000000000006','d3000000-0000-4000-8000-000000000003','d3000000-0000-4000-8000-000000000003','d5000000-0000-4000-8000-000000000005',now()+interval '1 day',now()+interval '25 hours',array[current_date+1],10000,1800,11800,now()+interval '5 minutes');
select public.save_discount_offer(to_jsonb(o)||jsonb_build_object('starts_at',now()-interval '1 day','ends_at',now()+interval '1 day','value',10,'value_kind','percent'),o.id,o.revision) from public.discount_offers o where id=current_setting('discount.cap')::uuid;
select throws_ok($$select public.quote_discounted_equipment('d5000000-0000-4000-8000-000000000006')$$,'42501','Current owned equipment quote required','another member equipment quote denied');
select set_config('request.jwt.claims','{"sub":"d3000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select set_config('discount.equipment',public.quote_discounted_equipment('d5000000-0000-4000-8000-000000000006')::text,true);
select is((current_setting('discount.equipment')::jsonb->>'total_paise')::bigint,10620::bigint,'equipment10 percent plus configured18 percent tax');
select is((select breakdown->>'equipment_quote_id' from private.discount_quotes where id=(current_setting('discount.equipment')::jsonb->>'discount_quote_id')::uuid),'d5000000-0000-4000-8000-000000000006','equipment source persisted');
select is((select breakdown->>'total_paise' from private.discount_quotes where id=(current_setting('discount.equipment')::jsonb->>'discount_quote_id')::uuid),'10620','tax inclusive equipment snapshot persisted');
select is((select expires_at from private.discount_quotes where id=(current_setting('discount.equipment')::jsonb->>'discount_quote_id')::uuid),(select expires_at from public.equipment_rental_quotes where id='d5000000-0000-4000-8000-000000000006'),'discount cannot outlive equipment source');
select is((select total_paise from public.equipment_rental_quotes where id='d5000000-0000-4000-8000-000000000006'),11800::bigint,'overlay never mutates existing payable quote');
select is((select payment_state from public.equipment_rental_quotes where id='d5000000-0000-4000-8000-000000000006'),'unpaid','overlay never claims payment');
select set_config('request.jwt.claims','{"sub":"d3000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select public.save_discount_offer(to_jsonb(o)||'{"personal_use":"repeat_until_expiry","per_member_limit":2}',o.id,o.revision) from public.discount_offers o where id=current_setting('discount.cap')::uuid;
select set_config('discount.repeat1',private.make_discount_quote('d3000000-0000-4000-8000-000000000003','equipment',10000,0)->>'discount_quote_id',true);
select set_config('discount.repeat2',private.make_discount_quote('d3000000-0000-4000-8000-000000000003','equipment',10000,0)->>'discount_quote_id',true);
select set_config('discount.repeat3',private.make_discount_quote('d3000000-0000-4000-8000-000000000003','equipment',10000,0)->>'discount_quote_id',true);
set local role service_role;
select set_config('discount.repeatreserve1',public.reserve_discount_quote(current_setting('discount.repeat1')::uuid,'d3000000-0000-4000-8000-000000000003','repeat-first-key')::text,true);
select lives_ok($$select public.settle_discount_reservation(current_setting('discount.repeatreserve1')::uuid,true)$$,'actual service captures first repeat use');
select set_config('discount.repeatreserve2',public.reserve_discount_quote(current_setting('discount.repeat2')::uuid,'d3000000-0000-4000-8000-000000000003','repeat-second-key')::text,true);
select lives_ok($$select public.settle_discount_reservation(current_setting('discount.repeatreserve2')::uuid,true)$$,'actual service captures second repeat use');
select throws_ok($$select public.reserve_discount_quote(current_setting('discount.repeat3')::uuid,'d3000000-0000-4000-8000-000000000003','repeat-third-key')$$,'40001','Offer changed or exhausted; requote','repeat per-member limit blocks third');
reset role;
select is((select count(*)::int from private.discount_redemptions where offer_id=current_setting('discount.cap')::uuid and state='captured'),2,'exactly two repeated uses consumed');
select set_config('request.jwt.claims','{"sub":"d3000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select ok(not exists(select 1 from jsonb_array_elements(public.my_discount_offers()) o where o->>'id'=current_setting('discount.cap')),'exhausted personal offer absent from available list');
select * from finish();
rollback;
